export type Lab = { code: string; capacity: number; floor: number };

// Derived from Lab: every field becomes a string, and new fields appear automatically.
export type Stringify<T> = { [K in keyof T]: string };
export type LabForm = Stringify<Lab>;

export function toForm(lab: Lab): LabForm {
  return { code: lab.code, capacity: String(lab.capacity), floor: String(lab.floor) };
}

import type { LabForm } from '../src/form.ts';
