export { f };

import type { LabForm } from '../src/form.ts';
const missing: LabForm = { code: 'BE-201', capacity: '40' }; // expect TS2741
export { missing };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toForm } from '../src/form.ts';
test('toForm', () => assert.deepEqual(toForm({ code: 'BE-201', capacity: 40, floor: 2 }), { code: 'BE-201', capacity: '40', floor: '2' }));

