// Wrong: returns the values, not functions returning them.
export type Getters<T> = { [K in keyof T]: T[K] };

export function toGetters(lab: Lab): Getters<Lab> {
  return { code: lab.code, capacity: lab.capacity };
}

import { toGetters } from '../src/getters.ts';
const g = toGetters({ code: 'BE-201', capacity: 40 });
const code: string = g.code();     // calling the getter
const cap: number = g.capacity();
export { code, cap };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toGetters } from '../src/getters.ts';
test('getters', () => { const g = toGetters({ code: 'BE-201', capacity: 40 }); assert.equal(g.code(), 'BE-201'); assert.equal(g.capacity(), 40); });

solutionCodeJson.code:
export type Lab = { code: string; capacity: number };

// Every field becomes a function returning its value.
export type Getters<T> = { [K in keyof T]: () => T[K] };

export function toGetters(lab: Lab): Getters<Lab> {
  return { code: () => lab.code, capacity: () => lab.capacity };
}

import { toGetters } from '../src/getters.ts';
const g = toGetters({ code: 'BE-201', capacity: 40 });
const code: string = g.code();     // calling the getter
const cap: number = g.capacity();
export { code, cap };

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { toGetters } from '../src/getters.ts';
test('getters', () => { const g = toGetters({ code: 'BE-201', capacity: 40 }); assert.equal(g.code(), 'BE-201'); assert.equal(g.capacity(), 40); });

